// GENERATED by scripts/sync-engine.mjs from src/engine/kc.ts. Do not edit here: edit the original and run "npm run sync-engine".
// FAO-56 crop coefficient (Kc) resolution and ETc = Kc x ET0.
// Source: FAO Irrigation and Drainage Paper 56 (Allen et al., 1998)
//   - ETc = Kc ETo ............ Chapter 6, Eq. 58
//   - Kc ini / mid / end ...... Chapter 6, Table 12 (+ footnotes)
// Pure functions: no database, no network, no hidden defaults.
// A missing value is never treated as 0: the result says "unavailable" and why.

export type KcStage = 'ini' | 'mid' | 'end';

export interface Range {
  min: number;
  max: number;
}

export interface KcRow {
  rowId: number;
  sourceId: string;
  section: string;
  crop: string;
  variant: string | null;
  rowType: 'crop' | 'group_row';
  kc: { ini: Range | null; mid: Range | null; end: Range | null };
  /** Footnote ids exactly as printed in Table 12 (e.g. ['2']). */
  footnotes: { ini: string[]; mid: string[]; end: string[]; cropName: string[] };
}

export type KcResolution =
  | {
      status: 'ok';
      stage: KcStage;
      kc: Range;
      /** true when Table 12 gives a range (e.g. tomato Kc end 0.70-0.90): the caller must not silently pick one end. */
      isRange: boolean;
      origin: 'own' | 'group_row';
      /** Kc ini values are approximations for planning (Chapter 6, "Kc ini" section). */
      approximate: boolean;
      /** Footnotes the user/engine must review before trusting the number. */
      reviewFootnotes: string[];
      rowId: number;
      groupRowId: number | null;
      sourceId: string;
    }
  | { status: 'unavailable'; stage: KcStage; reason: 'not_in_table' };

const unique = (xs: string[]): string[] => [...new Set(xs)];

/**
 * Pick Kc for one growth stage.
 * - Uses the crop's own value when Table 12 has one.
 * - Only for 'ini': if the crop's cell is blank, uses the group row of the SAME section. Chapter 6 says that for
 *   several groups a single Kc ini is listed and is representative of the whole group. No such rule exists for
 *   mid/end, so those are never inherited.
 * - Otherwise: unavailable (never 0, never a guess).
 */
export function resolveKc(row: KcRow, groupRow: KcRow | null, stage: KcStage): KcResolution {
  const own = row.kc[stage];
  const base = [...row.footnotes[stage], ...row.footnotes.cropName, ...(stage === 'ini' ? ['1'] : [])];

  if (own) {
    return {
      status: 'ok',
      stage,
      kc: own,
      isRange: own.min !== own.max,
      origin: 'own',
      approximate: stage === 'ini',
      reviewFootnotes: unique(base),
      rowId: row.rowId,
      groupRowId: null,
      sourceId: row.sourceId,
    };
  }

  if (
    stage === 'ini' &&
    groupRow &&
    groupRow.rowType === 'group_row' &&
    groupRow.section === row.section &&
    groupRow.kc.ini
  ) {
    return {
      status: 'ok',
      stage,
      kc: groupRow.kc.ini,
      isRange: groupRow.kc.ini.min !== groupRow.kc.ini.max,
      origin: 'group_row',
      approximate: true,
      reviewFootnotes: unique([...base, ...groupRow.footnotes.ini]),
      rowId: row.rowId,
      groupRowId: groupRow.rowId,
      sourceId: row.sourceId,
    };
  }

  return { status: 'unavailable', stage, reason: 'not_in_table' };
}

export type EtcResult =
  | { status: 'ok'; etc: Range }
  | { status: 'unavailable'; reason: 'kc_missing' | 'et0_missing' | 'et0_invalid' };

/**
 * ETc = Kc x ET0   (FAO-56, Chapter 6, Eq. 58)
 * ETc has the same unit as ET0 (mm/day if ET0 is mm/day). ET0 = 0 is a valid number; null/undefined is "missing".
 * Returns a range because some Kc values in Table 12 are ranges.
 */
export function computeEtc(kc: Range | null, et0: number | null | undefined): EtcResult {
  if (kc === null) return { status: 'unavailable', reason: 'kc_missing' };
  if (et0 === null || et0 === undefined) return { status: 'unavailable', reason: 'et0_missing' };
  if (!Number.isFinite(et0) || et0 < 0) return { status: 'unavailable', reason: 'et0_invalid' };
  return { status: 'ok', etc: { min: kc.min * et0, max: kc.max * et0 } };
}
